# Task: Implement Flush Operation Ordering and Batching

## Context
The flush operation takes all pending changes in the Session and writes them to the database in the correct order to respect foreign key constraints and maximize performance through batching.

## Critical Ordering Rules
1. **DELETE child-first**: Delete children before parents (FK constraint)
2. **INSERT parent-first**: Insert parents before children (FK constraint)
3. **UPDATE any order**: Updates can happen in any order (assuming no circular FK)
4. **Batch same-type operations**: Batch INSERTs and DELETEs per table

## What to Implement

### 1. Operation Types
\`\`\`rust
/// A pending database operation.
#[derive(Debug)]
pub enum PendingOp {
    Insert {
        key: ObjectKey,
        table: &'static str,
        columns: Vec<&'static str>,
        values: Vec<Value>,
    },
    Update {
        key: ObjectKey,
        table: &'static str,
        pk_columns: Vec<&'static str>,
        pk_values: Vec<Value>,
        set_columns: Vec<&'static str>,
        set_values: Vec<Value>,
    },
    Delete {
        key: ObjectKey,
        table: &'static str,
        pk_columns: Vec<&'static str>,
        pk_values: Vec<Value>,
    },
}

impl PendingOp {
    pub fn table(&self) -> &str {
        match self {
            PendingOp::Insert { table, .. } => table,
            PendingOp::Update { table, .. } => table,
            PendingOp::Delete { table, .. } => table,
        }
    }

    pub fn is_insert(&self) -> bool { matches!(self, PendingOp::Insert { .. }) }
    pub fn is_update(&self) -> bool { matches!(self, PendingOp::Update { .. }) }
    pub fn is_delete(&self) -> bool { matches!(self, PendingOp::Delete { .. }) }
}
\`\`\`

### 2. Dependency Graph for Ordering
\`\`\`rust
/// Builds a dependency graph from table foreign key relationships.
pub struct FlushOrderer {
    /// Table -> tables it depends on (has FK to)
    dependencies: HashMap<&'static str, Vec<&'static str>>,
}

impl FlushOrderer {
    pub fn new() -> Self {
        Self { dependencies: HashMap::new() }
    }

    pub fn register_model<T: Model>(&mut self) {
        let table = T::TABLE_NAME;
        let deps: Vec<&'static str> = T::fields()
            .iter()
            .filter_map(|f| f.foreign_key)
            .map(|fk| fk.split('.').next().unwrap())
            .collect();
        self.dependencies.insert(table, deps);
    }

    /// Order operations for flush.
    /// Returns (deletes, inserts, updates) in correct order.
    pub fn order(&self, ops: Vec<PendingOp>) -> FlushPlan {
        let mut deletes = Vec::new();
        let mut inserts = Vec::new();
        let mut updates = Vec::new();

        for op in ops {
            match op {
                PendingOp::Delete { .. } => deletes.push(op),
                PendingOp::Insert { .. } => inserts.push(op),
                PendingOp::Update { .. } => updates.push(op),
            }
        }

        // Sort deletes: children first (reverse topological order)
        deletes.sort_by(|a, b| {
            let a_deps = self.dependencies.get(a.table()).map(|d| d.len()).unwrap_or(0);
            let b_deps = self.dependencies.get(b.table()).map(|d| d.len()).unwrap_or(0);
            b_deps.cmp(&a_deps) // More deps = delete first
        });

        // Sort inserts: parents first (topological order)
        inserts.sort_by(|a, b| {
            let a_deps = self.dependencies.get(a.table()).map(|d| d.len()).unwrap_or(0);
            let b_deps = self.dependencies.get(b.table()).map(|d| d.len()).unwrap_or(0);
            a_deps.cmp(&b_deps) // Fewer deps = insert first
        });

        FlushPlan { deletes, inserts, updates }
    }
}
\`\`\`

### 3. Batch Execution
\`\`\`rust
pub struct FlushPlan {
    pub deletes: Vec<PendingOp>,
    pub inserts: Vec<PendingOp>,
    pub updates: Vec<PendingOp>,
}

impl FlushPlan {
    /// Execute the flush plan against the database.
    pub async fn execute(&self, conn: &mut impl Connection) -> Result<FlushResult> {
        let mut result = FlushResult::default();

        // Execute deletes (batched by table)
        for batch in self.batch_by_table(&self.deletes) {
            let count = self.execute_delete_batch(conn, batch).await?;
            result.deleted += count;
        }

        // Execute inserts (batched by table)
        for batch in self.batch_by_table(&self.inserts) {
            let count = self.execute_insert_batch(conn, batch).await?;
            result.inserted += count;
        }

        // Execute updates (one at a time - different columns may be dirty)
        for op in &self.updates {
            self.execute_update(conn, op).await?;
            result.updated += 1;
        }

        Ok(result)
    }

    async fn execute_insert_batch(&self, conn: &mut impl Connection, ops: &[&PendingOp]) -> Result<usize> {
        if ops.is_empty() { return Ok(0); }

        // Build multi-row INSERT
        // INSERT INTO table (col1, col2) VALUES (?, ?), (?, ?), ...
        let table = ops[0].table();
        let columns = match ops[0] {
            PendingOp::Insert { columns, .. } => columns,
            _ => unreachable!(),
        };

        let mut sql = format!("INSERT INTO {} ({}) VALUES ", table, columns.join(", "));
        let mut params = Vec::new();

        for (i, op) in ops.iter().enumerate() {
            if let PendingOp::Insert { values, .. } = op {
                if i > 0 { sql.push_str(", "); }
                let placeholders: Vec<_> = (0..values.len()).map(|_| "?").collect();
                sql.push_str(&format!("({})", placeholders.join(", ")));
                params.extend(values.iter().cloned());
            }
        }

        conn.execute(&sql, &params).await?;
        Ok(ops.len())
    }

    async fn execute_delete_batch(&self, conn: &mut impl Connection, ops: &[&PendingOp]) -> Result<usize> {
        // DELETE FROM table WHERE pk IN (?, ?, ?)
        // ...
    }

    fn batch_by_table<'a>(&self, ops: &'a [PendingOp]) -> Vec<Vec<&'a PendingOp>> {
        // Group ops by table name
        // ...
    }
}

#[derive(Debug, Default)]
pub struct FlushResult {
    pub inserted: usize,
    pub updated: usize,
    pub deleted: usize,
}
