\`\`\`rust
/// E2E: Full flush workflow with parent-child relationships
#[tokio::test]
async fn e2e_flush_parent_child_ordering() {
    let pool = setup_test_pool().await;
    let mut session = Session::new(&pool).await.unwrap();

    // Add parent and child in wrong order (child first)
    let hero = Hero { id: None, name: "Batman".into(), team_id: Some(1) };
    let team = Team { id: Some(1), name: "Justice League".into() };

    session.add(&hero); // Child added first
    session.add(&team); // Parent added second

    tracing::info!("Added hero then team - flush should reorder");

    // Flush should insert Team before Hero
    session.flush().await.unwrap();

    // Verify both in DB
    let db_team = session.get::<Team>(1).await.unwrap();
    assert!(db_team.is_some());

    let db_hero = session.query::<Hero>()
        .filter(name.eq("Batman"))
        .one()
        .await
        .unwrap();
    assert!(db_hero.is_some());

    tracing::info!("Flush succeeded with correct ordering");
}

/// E2E: Batch insert performance
#[tokio::test]
async fn e2e_flush_batch_performance() {
    let pool = setup_test_pool().await;
    let mut session = Session::new(&pool).await.unwrap();

    // Add 1000 heroes
    for i in 0..1000 {
        let hero = Hero { id: None, name: format!("Hero {}", i), team_id: None };
        session.add(&hero);
    }

    let start = std::time::Instant::now();
    let query_count_before = get_query_count(&pool);

    session.flush().await.unwrap();

    let elapsed = start.elapsed();
    let query_count_after = get_query_count(&pool);

    tracing::info!(
        elapsed_ms = elapsed.as_millis(),
        queries = query_count_after - query_count_before,
        "Flushed 1000 inserts"
    );

    // Should use batched inserts, not 1000 individual queries
    assert!(query_count_after - query_count_before < 100, "Should batch inserts");
}

/// E2E: Delete ordering respects FK
#[tokio::test]
async fn e2e_flush_delete_ordering() {
    // Setup: Team with 5 Heroes
