            description = %migration.description,
            format = ?self.format,
            "Writing migration file"
        );

        // ... write logic ...

        tracing::info!(path = %path.display(), "Migration file written");
        Ok(path)
    }
}

impl<'c> MigrationRunner<'c> {
    #[tracing::instrument(level = "info", skip(self, migration))]
    pub async fn apply(&mut self, migration: &Migration) -> Result<()> {
        tracing::info!(
            version = %migration.version,
            statements = migration.up.len(),
            "Applying migration"
        );

        for (i, stmt) in migration.up.iter().enumerate() {
            tracing::debug!(index = i, sql = %stmt, "Executing statement");
            self.conn.execute(stmt, &[]).await?;
        }

        tracing::info!(version = %migration.version, "Migration applied successfully");
        Ok(())
    }
}
