/// E2E: Lazy loading workflow
#[tokio::test]
async fn e2e_lazy_loading_single() {
    let pool = setup_test_pool().await;
    let mut session = Session::new(&pool).await.unwrap();

    // Create Hero with team_id pointing to Team
    let hero = session.query::<Hero>()
        .filter(id.eq(1))
        .one()
        .await
        .unwrap()
        .unwrap();

    // Lazy field not yet loaded
    assert!(!hero.team.is_loaded());
    tracing::debug!("Before load: team not loaded");

    // Load the team
    let team = hero.team.load(&mut session).await.unwrap();
    assert!(team.is_some());
    tracing::info!(team_name = %team.unwrap().name, "Loaded team");

    // Now cached
    assert!(hero.team.is_loaded());
    assert_eq!(hero.team.get(), team);
}

/// E2E: Batch loading prevents N+1
#[tokio::test]
async fn e2e_lazy_batch_loading() {
    let pool = setup_test_pool().await;
    let mut session = Session::new(&pool).await.unwrap();

    // Load 100 heroes
    let mut heroes = session.query::<Hero>().all().await.unwrap();

    // Without batch loading: 100 queries (N+1 problem)
    // With batch loading: 1 query

    let query_count_before = get_query_count(&session);

    session.load_many(&mut heroes, |h| &mut h.team).await.unwrap();

    let query_count_after = get_query_count(&session);
    assert_eq!(query_count_after - query_count_before, 1, "Should be single batched query");

    // All teams loaded
    for hero in &heroes {
        if hero.team.fk().is_some() {
            assert!(hero.team.is_loaded());
        }
    }
}
