# Task: Implement Expression System

## Context
The expression system is the foundation for building WHERE clauses, ORDER BY, and computed columns. It must be type-safe and generate correct SQL for each dialect.

## Expression Types

### Core Expression Enum
```rust
#[derive(Debug, Clone)]
pub enum Expr {
    /// Column reference: "users"."name"
    Column {
        table: Option<String>,
        name: String,
    },

    /// Literal value: 42, 'hello', NULL
    Literal(Value),

    /// Binary operation: a = b, a > b, a AND b
    Binary {
        left: Box<Expr>,
        op: BinaryOp,
        right: Box<Expr>,
    },

    /// Unary operation: NOT a, -a, a IS NULL
    Unary {
        op: UnaryOp,
        expr: Box<Expr>,
    },

    /// Function call: COUNT(*), UPPER(name)
    Function {
        name: String,
        args: Vec<Expr>,
    },

    /// CASE WHEN ... THEN ... ELSE ... END
    Case {
        when_clauses: Vec<(Expr, Expr)>,
        else_clause: Option<Box<Expr>>,
    },

    /// Subquery: (SELECT ...)
    Subquery(Box<Select<()>>),

    /// IN list: a IN (1, 2, 3)
    InList {
        expr: Box<Expr>,
        list: Vec<Expr>,
        negated: bool,
    },

    /// BETWEEN: a BETWEEN 1 AND 10
    Between {
        expr: Box<Expr>,
        low: Box<Expr>,
        high: Box<Expr>,
        negated: bool,
    },

    /// LIKE: name LIKE '%foo%'
    Like {
        expr: Box<Expr>,
        pattern: String,
        negated: bool,
    },

    /// Placeholder for bound parameters: $1, ?
    Placeholder(usize),

